===== Tablet/BadPairSequence.lean =====
import Tablet.IncreasingPair

-- [TABLET NODE: BadPairSequence]
def BadPairSequence {Q : Type} (r : Q → Q → Prop)
    (f : IncreasingPair → Q) : Prop :=
-- BODY
  ∀ (m n l : Nat) (hmn : m < n) (hnl : n < l),
    ¬ r (f ⟨m, n, hmn⟩) (f ⟨n, l, hnl⟩)


===== Tablet/BadPairSequence.tex =====
\begin{definition}[Bad sequence of sequences]
For a relation $r$ on $Q$, a map
$f:\mathsf{IncreasingPair}\to Q$ is bad when, for every $m<n<l$,
\[
\neg r\bigl(f(m,n),f(n,l)\bigr).
\]
Thus the map is the paper's sequence of sequences
$f:\,[\omega]^2\to Q$, and the condition is precisely its displayed
badness condition.
\end{definition}

===== Tablet/CardinalityFront.lean =====
import Tablet.Preamble

-- [TABLET NODE: CardinalityFront]
def CardinalityFront (k : Nat) (X : Set Nat) : Set (Finset Nat) :=
-- BODY
  {s | s.card = k ∧ (↑s : Set Nat) ⊆ X}


===== Tablet/CardinalityFront.tex =====
\begin{definition}[Constant-cardinality front]
For $k\in\mathbb N$ and an infinite $X\subseteq\mathbb N$, let
\[
\mathsf{CardinalityFront}(k,X)=\{s\subseteq X\mid s\text{ is finite and }|s|=k\}.
