  1471	Let $Q$ be a qo and $f:F\to Q$ be a super-sequence.
  1472	\begin{enumDefn}
  1473	\item We say that $f$ is \emph{bad} if whenever $s\tri t$ in $F$, we have $f(s)\nleq f(t)$.
  1474	\item We say that $f$ is \emph{good} if there exists $s,t\in F$ with $s\tri t$ and $f(s)\leq f(t)$.
  1475	\end{enumDefn}
  1476	\end{definition}
