  1478	 \begin{lemma}\label{badSimpsonNW}
  1479	 Let $Q$ be a quasi-order. 
  1480	 \begin{enumThm}
  1481	 \item If $h:\infSub{\omega}\to Q$ is locally constant and bad, then $h^{\dcl}:F^{h}\to Q$ is a bad super-sequence. \label{badSimpsonNW1}
  1482	 \item If $f:F\to Q$ is a bad super-sequence from a front on $X$, then $f^{\upcl}:\infSub{X}\to Q$ is a bad locally constant multi-sequence.\label{badSimpsonNW2}
  1483	 \end{enumThm}
  1484	 \end{lemma}
  1485	\begin{proof}
  1486	\begin{itemize} 
  1487	\item[\cref{badSimpsonNW1}] Suppose $h:\infSub{X}\to Q$ is locally constant and bad. Let us show that $h^{\dcl}:F^{h}\to Q$ is bad. If $s,t\in F^{h}$ with $s\tri t$, i.e. there exists $Y\in\infSub{X}$ such that $s\segs Y$ and $t\segs \shift{Y}$. Then $h^{\dcl}(s)=h(Y)$ and $h^{\dcl}(t)=h(\shift{Y})$ and since $h$ is assumed to be bad, we have $h^{\dcl}(s)\nleq h^{\dcl}(t)$.
  1488	 
  1489	\item[\cref{badSimpsonNW2}] Suppose $f:F\to Q$ is bad from a front on $X$ and let $Y\in\infSub{X}$. There are unique $s,t\in F$ such that $s\segs Y$ and $t\segs \shift{Y}$, and clearly $f^{\upcl}(Y)=f(s)$, $f^{\upcl}(\shift{Y})=f(t)$, and $s\tri t$. Therefore $f^{\upcl}(Y)\nleq f^{\upcl}(\shift{Y})$ holds. \qedhere
  1490	\end{itemize}
  1491	 \end{proof}	
