   721	
   722	Importantly, a \wqo{} can be characterised in terms of its subsets.
   723	
   724	\begin{definition}
   725	Let $Q$ be a quasi-order.
   726	\begin{enumDefn}
   727	\item A subset $D$ of $Q$  is a \emph{downset}, or an \emph{initial segment}, if $q\in D$ and $p\leq q$ implies $p\in D$. For any $S\subseteq Q$, we write $\dcl S$ for the downset generated by $S$ in $Q$, i.e. the set $\{q\in Q\mid \exists p\in S \  q\leq p\}$. We also write $\dcl p$ for $\dcl\{p\}$.
   728	
   729	We denote by $\Down(Q)$ the partial order of downsets of $Q$ under inclusion.
   730	
   731	\item We give the dual meaning to \emph{upset}, $\upcl S$ and $\upcl q$ respectively. 
   732	
   733	\item An upset $U$ is said to to be \emph{finitely generated}, or to admit a \emph{finite basis}, if there exists a finite $F\subseteq U$ such that $U=\upcl F$. We say that $Q$ has \emph{the finite basis property} if every upset of $Q$ admits a finite basis.
   734	
   735	\item A downset $D\in \Down(Q)$ is said to be \emph{finitely bounded}, if there exists a finite set $F\subseteq Q$ with $D=Q\setminus \upcl F$. We let $\DownFb(Q)$ be the set of finitely bounded downsets partially ordered by inclusion.
   736	
   737	\item We turn the power-set of $Q$, denoted $\mathcal{P}(Q)$, into a quasi-order by letting $X\leq Y$ if and only if $\forall p\in X\ \exists q\in Y\ p\leq q$, this is sometimes called the \emph{domination quasi-order}. We let $\CtblSubs(Q)$ be the the set of countable subsets of $Q$ with the quasi-order induced from $\mathcal{P}(Q)$. Since $X\leq Y$ if and only if $\dcl X \subseteq \dcl Y$, the equivalent partial order of $\mathcal{P}(Q)$ is $\Down(Q)$ and the quotient map is given by $X\mapsto \dcl X$.
   738	
   739	\end{enumDefn}
   740	\end{definition}
   741	
   742	The notion of well-quasi-order should be thought of as a generalisation of the notion of well-ordering beyond linear orders. Recall that a partial order $P$ is a linear order if for every $p$ and $q$ in $P$, either $p\leq q$ or $q\leq p$. A \emph{well-ordering} is (traditionally, the associated strict relation $<$ of) a partial order that is both linearly ordered and well-founded. 
   743	
   744	Observe that a linearly ordered $P$ is well-founded if and only if the initial segments of $P$ are well-founded under inclusion. Considering for example the partial order $(\omega,=)$, one directly sees that a partial order $P$ can be well-founded while the initial segments of $P$ (here $\mathcal{P}(\omega)$) are not well-founded under inclusion. However a quasi-order $Q$ is \wqo{} if and only if the initial segments of $Q$ are well-founded under inclusion.
   745	
   746	
   747	
   748	\begin{proposition}\label{prop:ClassicEquWqo2}
   749	A quasi-order $Q$ is a \wqo{} if and only if one of the following equivalent conditions is fulfilled:
   750	\begin{enumWqo}[Wqo]
   751	\item \label{Item:4}$Q$ has the finite basis property,
   752	
   753	\item \label{Item:5}$(\mathcal{P}(Q),\leq)$ is well-founded,
   754	
   755	\item \label{Item:5b}$(\CtblSubs(Q),\leq)$ is well-founded,
   756	
   757	\item \label{Item:6}$(\Down(Q),\subseteq)$ is well-founded,
   758	
   759	\item \label{Item:6b} $(\DownFb(Q),\subseteq)$ is well-founded.
   760	\end{enumWqo}
   761	\end{proposition}
   762	
   763	\begin{proof} 
   764	\begin{descProofUp}
   765	\item[\cref{Item:2}$ \to $\cref{Item:4}] We prove the contrapositive. Suppose $S\in\Final(Q)$ admits no finite basis. Since $\emptyset=\upcl \emptyset$, $S\neq \emptyset$. By dependent choice, we can show the existence of a bad sequence $f:\omega \to Q$. Choose $f(0)\in S$ and suppose that $f$ is defined up to some $n>0$. Since $\upcl \{f(0),\ldots f(n)\}\subset S$ we can choose some $f(n+1)$ inside $S\setminus \upcl \{f(0),\ldots f(n)\}$.
   766	
   767	\item [\cref{Item:4}$ \to$\cref{Item:5}] We prove the contrapositive again. Suppose that $(X_{n})_{n\in\omega}$ is an infinite descending chain in $\mathcal{P}(Q)$. Then for each $n\in\omega$ we choose $q_{n}\in \dcl X_{n}\setminus \dcl X_{n+1}$. Then $\{q_{n}\mid n\in\omega\}$ has no finite basis. Indeed for all $n\in \omega$ we have $q_{n+1}\notin\upcl \{q_{i}\mid i\leq n\}$, otherwise $q_{i}\leq q_{n+1}\in \dcl X_{n+1}\subseteq \dcl X_{i+1}$ for some $i\leq n$, a contradiction.
   768	
   769	\item[\cref{Item:5}$ \to $\cref{Item:5b}] Obvious.
   770	
   771	\item[\cref{Item:5b}$ \to $\cref{Item:2}] By contraposition, if $(q_{n})_{n\in\omega}$ is a bad sequence in $Q$, then $P_{n}=\{q_{k}\mid n\leq k\}$ is an infinite descending chain in $\CtblSubs(Q)$ since whenever $m<n$ we have $q_{m}\in P_{m}$ and $q_{m}\nleq q_{k}$ for every $k\geq n$.
   772	
   773	\item[\cref{Item:5}$ \to $\cref{Item:6}] By contraposition, any infinite descending chain for inclusion in $\Down(Q)$ is also an infinite descending chain in $(\mathcal{P}(Q),\leq)$.
   774	
   775	\item[\cref{Item:6}$ \to $\cref{Item:6b}] Obvious.
   776	
   777	\item[\cref{Item:6b}$\to$\cref{Item:2}] By contraposition, if $f:\omega\to Q$ is a bad sequence, then $n\mapsto D_{n}=Q\setminus \upcl \{f(i)\mid i\leq n\}$ is an infinite descending chain in $\DownFb(Q)$.\qedhere
   778	\end{descProofUp}
   779	\end{proof}
