===== Tablet/InitialSegment.tex =====
\begin{definition}
For finite subsets $u,v\subseteq\mathbb N$, write
$\mathsf{InitialSegment}(u,v)$ if either $u=v$, or there is an $n\in v$
such that
\[
u=\{k\in v\mid k<n\}.
\]
Thus this is the paper's initial-segment relation after identifying a finite
set with its increasing enumeration.
\end{definition}

===== Tablet/InitialSegment.lean =====
import Tablet.Preamble

-- [TABLET NODE: InitialSegment]
def InitialSegment (u v : Finset Nat) : Prop :=
-- BODY
  u = v ∨ ∃ n ∈ v, u = v.filter (fun k => k < n)

===== Tablet/ProperPrefixSet.tex =====
\begin{definition}
For a finite set $s$ and an infinite set $Y$ of naturals, write
$\mathsf{ProperPrefixSet}(s,Y)$ when some $n\in Y$ satisfies
\[
s=\{k\in Y\mid k<n\}.
\]
This is the paper's notation $s\segs Y$.
\end{definition}

===== Tablet/ProperPrefixSet.lean =====
import Tablet.Preamble

-- [TABLET NODE: ProperPrefixSet]
def ProperPrefixSet (s : Finset Nat) (Y : Set Nat) : Prop :=
-- BODY
  ∃ n, n ∈ Y ∧ ∀ k, k ∈ s ↔ k ∈ Y ∧ k < n

===== Tablet/FrontBase.tex =====
\begin{definition}
For a family $F$ of finite subsets of $\mathbb N$, its base is
\[
\mathsf{FrontBase}(F)=\{n\in\mathbb N\mid \text{there is an }s\in F
\text{ with }n\in s\}.
\]
\end{definition}

===== Tablet/FrontBase.lean =====
import Tablet.Preamble

-- [TABLET NODE: FrontBase]
def FrontBase (F : Set (Finset Nat)) : Set Nat :=
-- BODY
  {n | ∃ s, s ∈ F ∧ n ∈ s}

===== Tablet/FrontRestriction.tex =====
\begin{lemma}[Restriction closure]
If $F$ is a front on $X$ and $Y\subseteq X$ is infinite, then
$F\mathbin{|}Y$ is a front on $Y$.
\end{lemma}
\begin{proof}
Prefix-freeness is inherited from $F$.  By the operation in
\noderef{FrontRestrict}, if $Z\subseteq Y$ is infinite,
then $Z\subseteq X$ is infinite, so density of $F$ gives an $s\in F$ with
$s\segs Z$.  Since $s\subseteq Z\subseteq Y$, this member lies in
$F\mathbin{|}Y$, proving density.  The base of the restriction is contained
in $Y$ by definition.  Conversely, for each $n\in Y$, density applied to
$\{n\}\cup Y/n$ gives a member of the restriction containing $n$; hence its
base is $Y$ unless the restriction is trivial.  The exceptional case is
allowed by the first clause of \noderef{Front}.  Thus all three clauses of
the front definition hold.
\end{proof}

