\begin{definition}
For a family $F$ of finite sets and $Y\subseteq\mathbb N$, define
\[
F\mathbin{|}Y=\{s\in F\mid s\subseteq Y\}.
\]
This is the restriction operation used to produce sub-fronts.
\end{definition}

